package dev.aether.modules.inventorymanager

import dev.aether.config.AetherConfig
import dev.aether.config.ConfigHelpers
import dev.aether.macro.farming.FarmingMacroManager
import dev.aether.macro.MacroState
import dev.aether.macro.MacroStateManager
import dev.aether.macro.MacroWorkerThread
import dev.aether.modules.gear.GearManager
import dev.aether.modules.gear.helpers.LoadoutManager
import dev.aether.modules.pest.PestManager
import dev.aether.modules.pest.helpers.PestPrepSwapManager
import dev.aether.util.ClientUtils
import net.minecraft.client.Minecraft
import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen
import net.minecraft.world.inventory.ContainerInput
import net.minecraft.world.inventory.Slot
import net.minecraft.world.item.ItemStack

class GeorgeManager private constructor() {
 companion object {
  private const val GEORGE_COOLDOWN_MS=30000L
  @JvmField @Volatile var isSelling=false
  @JvmField @Volatile var isPreparingToSell=false
  @JvmField @Volatile var interactionStage=0
  @JvmField @Volatile var interactionTime=0L
  @JvmField @Volatile var confirmationCount=0
  private var lastGeorgeSellAttemptTime=0L
  private var lastGeorgeGuiCloseTime=0L
  private var lastGeorgeSequenceActionTime=0L
  private fun getPrepRequiredState()=if(AetherConfig.FARM_WHILE_CALLING_GEORGE.get())MacroState.State.FARMING else MacroState.State.GEORGE
  private fun pauseFarmingForGeorgeIfNeeded(){if(!AetherConfig.FARM_WHILE_CALLING_GEORGE.get()&&MacroStateManager.getCurrentState()==MacroState.State.FARMING)MacroStateManager.setCurrentState(MacroState.State.GEORGE)}
  private fun resumeFarmingAfterGeorgeWait(client:Minecraft,debugMessage:String){if(AetherConfig.FARM_WHILE_CALLING_GEORGE.get()&&MacroStateManager.getCurrentState()==MacroState.State.GEORGE){MacroStateManager.setCurrentState(MacroState.State.FARMING);ClientUtils.sendDebugMessage(debugMessage)}}
  @JvmStatic fun reset(){isSelling=false;isPreparingToSell=false;interactionStage=0;interactionTime=0;confirmationCount=0;lastGeorgeSellAttemptTime=0;lastGeorgeGuiCloseTime=0;lastGeorgeSequenceActionTime=0}
  @JvmStatic fun onCallGeorgeSent(){if(!shouldUseGeorgeAutomation()&&!isPreparingToSell&&!isSelling)return;isSelling=true;interactionStage=0;interactionTime=System.currentTimeMillis();confirmationCount=0;lastGeorgeGuiCloseTime=0;lastGeorgeSequenceActionTime=0}
  @JvmStatic fun handleGeorgeMenu(client:Minecraft,screen:AbstractContainerScreen<*>?){val p=client.player?:return;if(screen==null)return;if(!shouldUseGeorgeAutomation()){reset();return};val title=stripFormatting(screen.title.string);val isGeorgeGUI=isGeorgeScreen(title);val isGeorgeInteractionGUI=isGeorgeInteractionScreen(title);if(!isSelling&&!isPreparingToSell){if(!MacroStateManager.isMacroRunning())return;if(isGeorgeGUI){ClientUtils.sendMessage("§cUnexpected George GUI detected. Closing and returning to sequence...",false);p.closeContainer();MacroWorkerThread.getInstance().submit("George-UnexpectedGUI-Failsafe"){if(MacroWorkerThread.shouldAbortTask(client))return@submit;client.execute{FarmingMacroManager.disable(client)};MacroWorkerThread.sleep(1000);if(MacroWorkerThread.shouldAbortTask(client))return@submit;ClientUtils.sendDebugMessage("Restarting macro after unexpected George GUI closure");client.execute{FarmingMacroManager.enable(client,FarmingMacroManager.createMacroFromConfig())}}};return};lastGeorgeGuiCloseTime=0;if(!isGeorgeInteractionGUI)return;if(isSelling&&isGeorgeGUI&&MacroStateManager.getCurrentState()==MacroState.State.FARMING){MacroStateManager.setCurrentState(MacroState.State.GEORGE);ClientUtils.sendMessage("§eGeorge GUI detected. Pausing farming.",true)};val now=System.currentTimeMillis();if(now-interactionTime<ClientUtils.getGuiClickDelayMs(interactionStage==0))return;if(title.contains("offer pets")&&interactionStage<1){interactionStage=1;ClientUtils.sendDebugMessage("Stage 1: Offer pets menu detected");interactionTime=now}else if((title.contains("confirm")||title.contains("are you sure"))&&interactionStage<3){interactionStage=3;ClientUtils.sendDebugMessage("Stage 3: confirm sale gui screen");interactionTime=now};when(interactionStage){0->{if(title.contains("george")||title.contains("sell pets")||title.contains("pet collector")){val idx=findPetSlotIdx(screen);if(idx!=-1){val name=screen.menu.slots[idx].item.hoverName.string;ClientUtils.sendMessage("§aSelling pet: $name",true);ClientUtils.performSlotClick(screen,idx,0,ContainerInput.QUICK_MOVE);interactionTime=now;lastGeorgeSequenceActionTime=now}else if(countPetsInInventory(p)==0)finishSelling(client)}};1->{val slot13=if(screen.menu.slots.size>13)screen.menu.slots[13] else null;if(slot13!=null&&slot13.hasItem()&&isRatOrSlug(slot13.item)){interactionStage=2;ClientUtils.sendDebugMessage("Stage 2: rat/slug pet in slot 13");interactionTime=now}else{val idx=findPetSlotIdx(screen);if(idx!=-1&&idx!=13){ClientUtils.performSlotClick(screen,idx,0,ContainerInput.QUICK_MOVE);interactionTime=now;lastGeorgeSequenceActionTime=now}}};2->{if(title.contains("offer pets")){val idx=findButtonSlot(screen,"sell pet","accept","confirm","offer");if(idx!=-1&&client.gameMode!=null){ClientUtils.performSlotClick(screen,idx,0,ContainerInput.PICKUP);interactionTime=now;lastGeorgeSequenceActionTime=now}}};3->{val idx=findButtonSlot(screen,"confirm","yes","accept","click to accept");if(idx!=-1){ClientUtils.performSlotClick(screen,idx,0,ContainerInput.PICKUP);interactionTime=now+500;lastGeorgeSequenceActionTime=now}}}}
  private fun isPriorityEventActive(client:Minecraft):Boolean{val state=MacroStateManager.getCurrentState();if(state!=MacroState.State.FARMING&&state!=MacroState.State.GEORGE)return true;return PestManager.isCleaningInProgress()||PestPrepSwapManager.wasPrepSwappedForCurrentCycle()||BookCombineManager.isCombining||BookCombineManager.isPreparingToCombine||JunkManager.isDropping||JunkManager.isPreparingToDrop||AutoSellManager.isSelling||AutoSellManager.isPreparingToSell}
  @JvmStatic fun update(){val client=Minecraft.getInstance();val p=client.player;if(!shouldUseGeorgeAutomation()||p==null){if(isSelling||isPreparingToSell)reset();return};if(System.currentTimeMillis()-lastGeorgeSellAttemptTime<GEORGE_COOLDOWN_MS)return;if(isPreparingToSell){if(isPriorityEventActive(client)){isPreparingToSell=false;if(MacroStateManager.getCurrentState()==MacroState.State.GEORGE)MacroStateManager.setCurrentState(MacroState.State.FARMING);lastGeorgeSellAttemptTime=System.currentTimeMillis();ClientUtils.sendMessage("§cAborting George prep due to priority event.",false)};return};if(isSelling){if(isPriorityEventActive(client)){isSelling=false;lastGeorgeGuiCloseTime=0;lastGeorgeSequenceActionTime=0;if(MacroStateManager.getCurrentState()==MacroState.State.GEORGE)MacroStateManager.setCurrentState(MacroState.State.FARMING);ClientUtils.sendMessage("§cAborting George sell due to priority event.",false);lastGeorgeSellAttemptTime=System.currentTimeMillis();return};if(client.gui.screen()==null){resumeFarmingAfterGeorgeWait(client,"George GUI closed. Resuming farming until next re-call.");if(interactionStage>0){if(interactionStage>=3)ClientUtils.sendDebugMessage("Stage 4: gui closed");interactionStage=0};val now=System.currentTimeMillis();if(lastGeorgeGuiCloseTime==0L){lastGeorgeGuiCloseTime=now;return};val delay=ConfigHelpers.getRandomizedDelay(AetherConfig.GEORGE_POST_SELL_DELAY_MIN_MS.get(),AetherConfig.GEORGE_POST_SELL_DELAY_MAX_MS.get());val ready=maxOf(lastGeorgeGuiCloseTime,lastGeorgeSequenceActionTime);if(now-ready<delay)return;if(now-interactionTime>1500){val remaining=countPetsInInventory(p);if(remaining>0){ClientUtils.sendMessage("§7GUI closed, but $remaining pets remain. Re-calling George...",false);interactionTime=now;interactionStage=0;confirmationCount=0;lastGeorgeSequenceActionTime=0;ClientUtils.sendCommand("/call george")}else finishSelling(client)}};return};if(isPriorityEventActive(client)||LoadoutManager.isSwappingLoadout)return;val count=countPetsInInventory(p);if(count>=AetherConfig.GEORGE_SELL_THRESHOLD.get())triggerAutomaticSell(client,count)}
  private fun finishSelling(client:Minecraft){client.player?.let{p->if(client.gui.screen()!=null)p.closeContainer()};isSelling=false;isPreparingToSell=false;lastGeorgeGuiCloseTime=0;lastGeorgeSequenceActionTime=0;if(MacroStateManager.getCurrentState()==MacroState.State.GEORGE)MacroStateManager.setCurrentState(MacroState.State.FARMING);lastGeorgeSellAttemptTime=System.currentTimeMillis();ClientUtils.sendMessage("§aGeorge autosell finished. Resuming tasks...",true);client.execute{GearManager.swapToFarmingTool(client)}}
  @JvmStatic fun getSellablePetCount(client:Minecraft?):Int{val p=client?.player?:return 0;return countPetsInInventory(p)}
  @JvmStatic fun getGeorgeCooldownRemainingMs()=maxOf(0L,GEORGE_COOLDOWN_MS-(System.currentTimeMillis()-lastGeorgeSellAttemptTime))
  @JvmStatic fun shouldDelayPestTrigger()=shouldDelayPestTrigger(AetherConfig.FARM_WHILE_CALLING_GEORGE.get(),isPreparingToSell,isSelling)
  @JvmStatic fun shouldDelayPestTrigger(farmWhileCalling:Boolean,preparing:Boolean,selling:Boolean)=farmWhileCalling&&(preparing||selling)
  private fun countPetsInInventory(p:net.minecraft.world.entity.player.Player):Int{var count=0;for(i in 0 until 36){val stack=p.inventory.getItem(i);if(!stack.isEmpty){val name=stripFormatting(stack.hoverName.string);if((name.contains("rat")||name.contains("slug"))&&name.contains("[lvl 1]"))count++}};return count}
  private fun findPetSlotIdx(screen:AbstractContainerScreen<*>):Int{for(i in screen.menu.slots.indices){val slot=screen.menu.slots[i];if(slot.hasItem()&&isRatOrSlug(slot.item))return i};return -1}
  private fun isRatOrSlug(stack:ItemStack?):Boolean{if(stack==null||stack.isEmpty)return false;val name=stripFormatting(stack.hoverName.string);return (name.contains("rat")||name.contains("slug"))&&name.contains("[lvl 1]")}
  private fun findButtonSlot(screen:AbstractContainerScreen<*>,vararg keywords:String):Int{for(i in screen.menu.slots.indices){val slot=screen.menu.slots[i];if(!slot.hasItem())continue;val stack=slot.item;val itemName=stack.hoverName.string.lowercase();val itemId=stack.item.toString().lowercase();for(keyword in keywords)if(itemName.contains(keyword)&&(itemId.contains("lime")||itemId.contains("green")||itemId.contains("emerald")||itemId.contains("terracotta")))return i};return -1}
  private fun triggerAutomaticSell(client:Minecraft,count:Int){if(AetherConfig.FARM_WHILE_CALLING_GEORGE.get())ClientUtils.sendMessage("§eGeorge sell threshold met. Starting prep while farming...",false)else{ClientUtils.sendMessage("§eGeorge sell threshold met. Pausing farming while calling George...",false);pauseFarmingForGeorgeIfNeeded()};isPreparingToSell=true;isSelling=false;lastGeorgeGuiCloseTime=0;lastGeorgeSequenceActionTime=0;MacroWorkerThread.getInstance().submit("George-TriggerSell"){try{for(i in 3 downTo 1){if(!isPreparingToSell||MacroWorkerThread.shouldAbortTask(client,getPrepRequiredState()))break;ClientUtils.sendMessage("§eCalling George in $i s...",true);MacroWorkerThread.sleep(1000)};if(isPreparingToSell){isPreparingToSell=false;isSelling=true;interactionStage=0;interactionTime=System.currentTimeMillis();confirmationCount=0;lastGeorgeGuiCloseTime=0;lastGeorgeSequenceActionTime=0;ClientUtils.sendCommand("/call george");ClientUtils.sendMessage(if(AetherConfig.FARM_WHILE_CALLING_GEORGE.get())"§aGeorge called. Continuing farming until GUI opens." else "§aGeorge called. Waiting for the GUI to open.",false)}}catch(e:Exception){e.printStackTrace()}}}
  private fun isGeorgeScreen(title:String)=title.contains("confirm sale")||title.contains("offer pets")
  private fun isGeorgeInteractionScreen(title:String)=isGeorgeScreen(title)||title.contains("george")||title.contains("sell pets")||title.contains("pet collector")
  private fun shouldUseGeorgeAutomation():Boolean{val state=MacroStateManager.getCurrentState();return AetherConfig.AUTO_GEORGE_SELL.get()&&(state==MacroState.State.FARMING||state==MacroState.State.GEORGE)}
  private fun stripFormatting(text:String)=text.replace(Regex("(?i)\u00A7."),"").lowercase()
 }
}
